{"command": "python3 -c "
lines = open('cartpole_q.py').readlines()
# find line with eps = max...
for i, line in enumerate(lines):
    if 'eps = max(a.eps_end, eps * a.eps_decay)' in line:
        # replace with linear decay
        lines[i] = '        eps = max(a.eps_end, a.eps_start - (a.eps_start - a.eps_end) * ((ep + 1) / a.episodes))\\n'
        break
open('cartpole_q_lin_eps.py', 'w').write(''.join(lines))
""}

